import { useState } from 'react';
import {
  Box,
  TextField,
  HelperText,
  Select,
  SelectOption,
  Switch,
  Button,
  Alert,
  Stack,
} from '@jinx-ui/react';

const ROLE_OPTIONS = [
  { value: 'member', label: 'Участник' },
  { value: 'admin', label: 'Администратор' },
  { value: 'viewer', label: 'Наблюдатель' },
];

const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [emailTouched, setEmailTouched] = useState(false);
  const [role, setRole] = useState('member');
  const [notify, setNotify] = useState(true);
  const [submitted, setSubmitted] = useState(false);

  const isEmailValid = EMAIL_REGEX.test(email);
  const showEmailError = emailTouched && email.length > 0 && !isEmailValid;
  const canSubmit = isEmailValid;

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!canSubmit) return;
    setSubmitted(true);
  };

  return (
    <Box
      as="form"
      onSubmit={handleSubmit}
      className="jx-p-lg jx-rounded-md jx-bg-surface"
      style={{ maxWidth: 420 }}
    >
      <Stack direction="column" gap="md">
        {submitted && (
          <Alert
            variant="success"
            onClose={() => setSubmitted(false)}
          >
            Приглашение отправлено
          </Alert>
        )}

        <Stack direction="column" gap="xs">
          <TextField
            id="invite-email"
            type="email"
            label="Email"
            placeholder="name@example.com"
            value={email}
            onChange={(event) => setEmail(event.target.value)}
            onBlur={() => setEmailTouched(true)}
            invalid={showEmailError}
          />
          <HelperText tone={showEmailError ? 'danger' : 'neutral'}>
            {showEmailError
              ? 'Похоже, это не похоже на email-адрес'
              : 'Мы отправим приглашение на этот адрес'}
          </HelperText>
        </Stack>

        <Select
          id="invite-role"
          label="Роль"
          value={role}
          onChange={(value) => setRole(value)}
        >
          {ROLE_OPTIONS.map((option) => (
            <SelectOption key={option.value} value={option.value}>
              {option.label}
            </SelectOption>
          ))}
        </Select>

        <Switch
          id="invite-notify"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
          label="Отправить уведомление"
        />

        <Button type="submit" variant="primary" disabled={!canSubmit}>
          Отправить приглашение
        </Button>
      </Stack>
    </Box>
  );
}

